// Private CA module (docs/design/front-door.md §3.10.1, ticket FD-13).
//
// Builds constrained client-certificate CAs, issues 90-day client certificates from a generated
// key or a submitted CSR, and generates CRLs. It persists through the FD-04 tables `private_cas`
// and `client_certificates`; FD-16 (PgBouncer), FD-17 (database clients), FD-28 (rollover) and
// FD-14 (TCP mTLS routes) build on the service functions at the bottom of this file.
//
// Key handling:
// - Keys are generated by node:crypto and exist in this process only as KeyObjects or as the PEM
//   string handed straight to `encryptSecret`. Certificates and CRLs are encoded in-process
//   (./x509.ts), so no key is ever written to disk, passed to a subprocess, or logged.
// - A CA key is sealed in `secrets` with AES-256-GCM under ARK_ROOT_KEY and its key ID
//   (`kind: "pki.ca_key"`, sensitivity `root`). The generic reveal endpoint refuses `root`
//   secrets, and the summaries returned here never include the key or its secret ID.
// - A generated client key is sealed as a `once` secret (`kind: "pki.client_key"`) for the
//   existing one-time reveal. CSR issuance stores no key at all.
//
// Every certificate carries subjectKeyIdentifier and authorityKeyIdentifier: Python 3.13+
// (`VERIFY_X509_STRICT` by default) rejects a chain whose certificates lack an AKI.

import {
  createPrivateKey,
  createPublicKey,
  generateKeyPairSync,
  randomBytes,
  verify,
  type KeyObject,
} from "node:crypto";

import { createId, decryptSecret, encryptSecret } from "@ark-stack/shared";
import { and, asc, desc, eq, ne } from "drizzle-orm";

import { db } from "../db.ts";
import { loadEnv } from "../env.ts";
import {
  clientCertificates,
  privateCas,
  secrets,
  managedDatabases,
  mailboxes,
  domainClaims,
  services,
  projects,
} from "../schema.ts";
import * as x509 from "./x509.ts";

// ---- Policy ------------------------------------------------------------------------------------

export const CA_PURPOSES = ["db-client", "tcp-client", "http-client"] as const;
export type CaPurpose = (typeof CA_PURPOSES)[number];
export type CaStatus = "active" | "retired" | "revoked";

export const CA_VALIDITY_YEARS = 5;
/** R6: client certificates are valid for exactly 90 days from issuance. */
export const CLIENT_CERT_VALIDITY_DAYS = 90;
/** §3.10.1: CRLs carry a 14-day nextUpdate unless the caller configures another. */
export const DEFAULT_CRL_NEXT_UPDATE_DAYS = 14;
export const CA_KEY_SECRET_KIND = "pki.ca_key";
export const CLIENT_KEY_SECRET_KIND = "pki.client_key";
/** CSR submissions are PEM text of at most 16 KiB (FD-17 hardening). */
export const MAX_CSR_PEM_BYTES = 16 * 1024;
/** RSA moduli above this are refused before any signature work (bounded verification cost). */
export const MAX_RSA_MODULUS_BITS = 8192;
const DAY_MS = 86_400_000;

/** RFC 5280 CRLReason codes Ark records. `certificateHold` is not used: revocation is final. */
export const CRL_REASONS = {
  unspecified: 0,
  keyCompromise: 1,
  cACompromise: 2,
  affiliationChanged: 3,
  superseded: 4,
  cessationOfOperation: 5,
  privilegeWithdrawn: 9,
} as const;
export type CrlReason = keyof typeof CRL_REASONS;

/** A request or input that the CA policy refuses. Messages never contain key material. */
export class PkiPolicyError extends Error {
  override name = "PkiPolicyError";
}

/**
 * A refused certificate signing request. Every CSR failure, malformed or against policy, is this
 * one type: the parser never lets a DER, crypto or runtime error escape (FD-17 hardening).
 */
export class CsrError extends PkiPolicyError {
  override name = "CsrError";
}

const CA_NAME = /^[A-Za-z0-9](?:[A-Za-z0-9 ._/-]{0,46}[A-Za-z0-9._-])?$/;
const SUBJECT_CN = /^[A-Za-z0-9_](?:[A-Za-z0-9 ._@/-]{0,62}[A-Za-z0-9._@-])?$/;

function wholeSeconds(date: Date) {
  return new Date(Math.floor(date.getTime() / 1000) * 1000);
}

function addYears(date: Date, years: number) {
  const result = new Date(date);
  result.setUTCFullYear(result.getUTCFullYear() + years);
  return result;
}

/** A random, positive, non-zero 128-bit serial (§3.10.1). */
function randomSerial() {
  for (;;) {
    const bytes = randomBytes(16);
    if (bytes.some((byte) => byte !== 0)) return bytes;
  }
}

/**
 * Client keys must be ECDSA on P-256 or P-384, or RSA with at least 3072 bits. Ark generates
 * P-256; the other shapes are accepted from CSRs because common client stacks produce them.
 */
export function assertClientKeyPolicy(key: KeyObject) {
  const details = key.asymmetricKeyDetails ?? {};
  if (key.asymmetricKeyType === "ec") {
    if (details.namedCurve === "prime256v1" || details.namedCurve === "secp384r1") return;
    throw new PkiPolicyError("Client keys on this curve are not accepted; use ECDSA P-256 or P-384.");
  }
  if (key.asymmetricKeyType === "rsa") {
    const bits = details.modulusLength ?? 0;
    if (bits < 3072)
      throw new PkiPolicyError("RSA client keys must be at least 3072 bits; ECDSA P-256 is preferred.");
    if (bits > MAX_RSA_MODULUS_BITS)
      throw new PkiPolicyError(`RSA client keys must be at most ${MAX_RSA_MODULUS_BITS} bits.`);
    // A huge public exponent would make every verification slow; real keys use 65537.
    const exponent = details.publicExponent ?? 0n;
    if (exponent < 3n || exponent > 0xffffffffn || exponent % 2n === 0n)
      throw new PkiPolicyError("RSA client keys must use a small odd public exponent such as 65537.");
    return;
  }
  throw new PkiPolicyError(
    `Client keys of type ${key.asymmetricKeyType ?? "unknown"} are not accepted; use ECDSA P-256.`,
  );
}

function caSubject(purpose: CaPurpose, name: string, id: string): x509.NameAttribute[] {
  // §3.10.1: CN = "Ark <purpose> CA <name>". The CA ID sits in its own serialNumber attribute so
  // every generation has a distinct DN while the CN stays within RFC 5280's 64-character bound.
  return [
    { type: "CN", value: `Ark ${purpose} CA ${name}` },
    { type: "serialNumber", value: id.replaceAll("_", "-") },
  ];
}

// ---- Pure certificate operations (no database) ---------------------------------------------------

export type CaMaterial = {
  certPem: string;
  privateKey: KeyObject;
  serial: string;
  fingerprintSha256: string;
  notBefore: Date;
  notAfter: Date;
};

/**
 * A new self-signed ECDSA P-256 CA: basicConstraints critical CA:TRUE pathlen:0, keyUsage
 * critical keyCertSign+cRLSign, SKI, and AKI = SKI. The key never leaves the returned KeyObject.
 */
export function createCaMaterial(input: {
  id: string;
  purpose: CaPurpose;
  name: string;
  now?: Date;
}): CaMaterial {
  if (!CA_PURPOSES.includes(input.purpose)) throw new PkiPolicyError("Unknown CA purpose.");
  if (!CA_NAME.test(input.name))
    throw new PkiPolicyError("CA names are 1-48 letters, digits, spaces, '.', '_', '/' or '-'.");
  if (!/^[A-Za-z0-9_]{1,64}$/.test(input.id)) throw new PkiPolicyError("Invalid CA ID.");
  if (`Ark ${input.purpose} CA ${input.name}`.length > 64)
    throw new PkiPolicyError("The full CA common name must be at most 64 characters.");
  const { privateKey } = generateKeyPairSync("ec", { namedCurve: "P-256" });
  const spki = x509.spkiDer(privateKey);
  const keyId = x509.keyIdentifier(spki);
  const notBefore = wholeSeconds(input.now ?? new Date());
  const notAfter = addYears(notBefore, CA_VALIDITY_YEARS);
  const subject = x509.name(caSubject(input.purpose, input.name, input.id));
  const serial = randomSerial();
  const tbs = x509.sequence(
    x509.explicit(0, x509.integer(2)),
    x509.integerFromBytes(serial),
    x509.ecdsaWithSha256(),
    subject,
    x509.sequence(x509.time(notBefore), x509.time(notAfter)),
    subject,
    spki,
    x509.explicit(
      3,
      x509.sequence(
        x509.extension(x509.OID.basicConstraints, true, x509.basicConstraintsValue(true, 0)),
        x509.extension(x509.OID.keyUsage, true, x509.keyUsageValue(["keyCertSign", "cRLSign"])),
        x509.extension(x509.OID.subjectKeyIdentifier, false, x509.subjectKeyIdentifierValue(keyId)),
        x509.extension(x509.OID.authorityKeyIdentifier, false, x509.authorityKeyIdentifierValue(keyId)),
      ),
    ),
  );
  const der = x509.signStructure(tbs, privateKey);
  return {
    certPem: x509.toPem("CERTIFICATE", der),
    privateKey,
    serial: x509.parseCertificate(der).serial,
    fingerprintSha256: x509.sha256Hex(der),
    notBefore,
    notAfter,
  };
}

export type CaSigner = { certPem: string; privateKey: KeyObject };

/** Read a CA certificate and check that the signing key belongs to it and that it is a CA. */
function inspectSigner(ca: CaSigner) {
  const parsed = x509.parseCertificate(x509.fromPem(ca.certPem, ["CERTIFICATE"]));
  if (!x509.spkiDer(ca.privateKey).equals(parsed.spki))
    throw new Error("The CA private key does not match the CA certificate.");
  const constraints = parsed.extensions.find((item) => item.id === x509.OID.basicConstraints);
  if (!constraints || !x509.decodeBasicConstraints(constraints.value).ca)
    throw new Error("The issuer certificate is not a CA.");
  const ski = parsed.extensions.find((item) => item.id === x509.OID.subjectKeyIdentifier);
  if (!ski) throw new Error("The CA certificate has no subjectKeyIdentifier.");
  return { ...parsed, keyId: x509.decodeSubjectKeyIdentifier(ski.value) };
}

export type IssuedCertificate = {
  certPem: string;
  serial: string;
  fingerprintSha256: string;
  notBefore: Date;
  notAfter: Date;
};

/**
 * Sign a client certificate for `publicKey`: EKU clientAuth, keyUsage critical digitalSignature,
 * basicConstraints critical CA:FALSE, SKI and AKI, valid for exactly 90 days from `now`. The
 * subject is set by Ark (CN = the client's login-role name, §3.10.1), never copied from a CSR.
 */
export function signClientCertificate(input: {
  ca: CaSigner;
  subjectCn: string;
  publicKey: KeyObject;
  now?: Date;
}): IssuedCertificate {
  if (!SUBJECT_CN.test(input.subjectCn))
    throw new PkiPolicyError("Certificate common names are 1-64 letters, digits, spaces or ._@/-.");
  const publicKey = input.publicKey.type === "private" ? createPublicKey(input.publicKey) : input.publicKey;
  assertClientKeyPolicy(publicKey);
  const issuer = inspectSigner(input.ca);
  const spki = x509.spkiDer(publicKey);
  if (spki.equals(issuer.spki)) throw new PkiPolicyError("A client certificate cannot reuse the CA key.");
  const notBefore = wholeSeconds(input.now ?? new Date());
  const notAfter = new Date(notBefore.getTime() + CLIENT_CERT_VALIDITY_DAYS * DAY_MS);
  if (notBefore < issuer.notBefore) throw new PkiPolicyError("The CA is not valid yet.");
  if (notAfter > issuer.notAfter)
    throw new PkiPolicyError(
      "The CA expires before a 90-day certificate would; issue from a new CA generation.",
    );
  const serial = randomSerial();
  const tbs = x509.sequence(
    x509.explicit(0, x509.integer(2)),
    x509.integerFromBytes(serial),
    x509.ecdsaWithSha256(),
    issuer.subjectDer,
    x509.sequence(x509.time(notBefore), x509.time(notAfter)),
    x509.name([{ type: "CN", value: input.subjectCn }]),
    spki,
    x509.explicit(
      3,
      x509.sequence(
        x509.extension(x509.OID.basicConstraints, true, x509.basicConstraintsValue(false)),
        x509.extension(x509.OID.keyUsage, true, x509.keyUsageValue(["digitalSignature"])),
        x509.extension(x509.OID.extendedKeyUsage, false, x509.extendedKeyUsageValue([x509.OID.clientAuth])),
        x509.extension(
          x509.OID.subjectKeyIdentifier,
          false,
          x509.subjectKeyIdentifierValue(x509.keyIdentifier(spki)),
        ),
        x509.extension(
          x509.OID.authorityKeyIdentifier,
          false,
          x509.authorityKeyIdentifierValue(issuer.keyId),
        ),
      ),
    ),
  );
  const der = x509.signStructure(tbs, input.ca.privateKey);
  return {
    certPem: x509.toPem("CERTIFICATE", der),
    serial: x509.parseCertificate(der).serial,
    fingerprintSha256: x509.sha256Hex(der),
    notBefore,
    notAfter,
  };
}

const CSR_SIGNATURES: Record<string, { hash: string; keyType: "ec" | "rsa" }> = {
  [x509.OID.ecdsaWithSha256]: { hash: "sha256", keyType: "ec" },
  [x509.OID.ecdsaWithSha384]: { hash: "sha384", keyType: "ec" },
  [x509.OID.ecdsaWithSha512]: { hash: "sha512", keyType: "ec" },
  [x509.OID.sha256WithRsa]: { hash: "sha256", keyType: "rsa" },
  [x509.OID.sha384WithRsa]: { hash: "sha384", keyType: "rsa" },
  [x509.OID.sha512WithRsa]: { hash: "sha512", keyType: "rsa" },
};

/** Requested KeyUsage bits a client CSR may carry. The issued certificate gets digitalSignature. */
const CSR_KEY_USAGES = new Set<x509.KeyUsage>(["digitalSignature", "keyEncipherment", "keyAgreement"]);

function assertRequestedExtensions(extensions: x509.ParsedExtension[]) {
  const seen = new Set<string>();
  for (const item of extensions) {
    if (seen.has(item.id)) throw new PkiPolicyError(`The CSR repeats extension ${item.id}.`);
    seen.add(item.id);
    switch (item.id) {
      case x509.OID.basicConstraints:
        if (x509.decodeBasicConstraints(item.value).ca)
          throw new PkiPolicyError("The CSR requests a CA certificate; client certificates cannot be CAs.");
        break;
      case x509.OID.keyUsage: {
        const refused = x509.decodeKeyUsage(item.value).filter((usage) => !CSR_KEY_USAGES.has(usage));
        if (refused.length)
          throw new PkiPolicyError(
            `The CSR requests key usages outside the client policy: ${refused.join(", ")}.`,
          );
        break;
      }
      case x509.OID.extendedKeyUsage: {
        const refused = x509
          .decodeExtendedKeyUsage(item.value)
          .filter((usage) => usage !== x509.OID.clientAuth);
        if (refused.length)
          throw new PkiPolicyError(
            `The CSR requests extended key usages other than clientAuth: ${refused.join(", ")}.`,
          );
        break;
      }
      case x509.OID.subjectKeyIdentifier:
        break; // Ark computes its own.
      default:
        throw new PkiPolicyError(
          `The CSR requests extension ${item.id}, which client certificates do not carry.`,
        );
    }
  }
}

/** Named curves a CSR key may use, by OID, matching `assertClientKeyPolicy`. */
const CSR_CURVES = new Set(["1.2.840.10045.3.1.7", "1.3.132.0.34"]);
/** Directory string tags accepted in a CSR subject (which Ark checks but never copies). */
const NAME_STRING_TAGS = new Set([0x0c, 0x13, 0x14, 0x16, 0x1c, 0x1e]);
const MAX_NAME_RDNS = 16;
const MAX_RDN_ATTRIBUTES = 8;
const MAX_CSR_ATTRIBUTES = 4;

function assertCsrName(node: x509.Node | undefined) {
  const rdns = x509.children(x509.expectTag(node, 0x30, "a subject Name"));
  if (rdns.length > MAX_NAME_RDNS) throw new x509.DerError("The CSR subject has too many components.");
  for (const rdn of rdns) {
    const attributes = x509.children(x509.expectTag(rdn, 0x31, "a RelativeDistinguishedName SET"));
    if (!attributes.length || attributes.length > MAX_RDN_ATTRIBUTES)
      throw new x509.DerError("Malformed RelativeDistinguishedName.");
    for (const attribute of attributes) {
      const parts = x509.children(x509.expectTag(attribute, 0x30, "an AttributeTypeAndValue"));
      if (parts.length !== 2) throw new x509.DerError("Malformed AttributeTypeAndValue.");
      x509.decodeOid(parts[0]);
      if (!NAME_STRING_TAGS.has(parts[1]!.tag)) throw new x509.DerError("Unsupported subject string type.");
    }
  }
}

/** Read the SubjectPublicKeyInfo shape before handing its bytes to node:crypto. */
function readCsrPublicKey(node: x509.Node | undefined): KeyObject {
  const spki = x509.expectTag(node, 0x30, "a SubjectPublicKeyInfo");
  const parts = x509.children(spki);
  if (parts.length !== 2) throw new x509.DerError("Malformed SubjectPublicKeyInfo.");
  const algorithm = x509.children(x509.expectTag(parts[0], 0x30, "a public key AlgorithmIdentifier"));
  if (algorithm.length > 2) throw new x509.DerError("Malformed public key AlgorithmIdentifier.");
  const keyOid = x509.decodeOid(algorithm[0]);
  if (keyOid === x509.OID.ecPublicKey) {
    if (algorithm[1]?.tag !== 0x06)
      throw new PkiPolicyError("EC client keys must name their curve; explicit parameters are refused.");
    if (!CSR_CURVES.has(x509.decodeOid(algorithm[1])))
      throw new PkiPolicyError("Client keys on this curve are not accepted; use ECDSA P-256 or P-384.");
  } else if (keyOid === x509.OID.rsaEncryption) {
    if (algorithm[1] && !(algorithm[1].tag === 0x05 && algorithm[1].content.length === 0))
      throw new x509.DerError("Malformed RSA key parameters.");
  } else {
    const known: Record<string, string> = {
      "1.3.101.112": "ed25519",
      "1.3.101.113": "ed448",
      "1.2.840.10040.4.1": "dsa",
      "1.2.840.113549.1.1.10": "rsa-pss",
    };
    throw new PkiPolicyError(
      `Client keys of type ${known[keyOid] ?? keyOid} are not accepted; use ECDSA P-256.`,
    );
  }
  const bits = x509.decodeBitString(parts[1], "a subjectPublicKey BIT STRING");
  if (bits.unused !== 0) throw new x509.DerError("Malformed subjectPublicKey BIT STRING.");
  let publicKey: KeyObject;
  try {
    publicKey = createPublicKey({ key: Buffer.from(spki.raw), format: "der", type: "spki" });
  } catch {
    throw new PkiPolicyError("The CSR public key cannot be read.");
  }
  if (publicKey.asymmetricKeyType !== (keyOid === x509.OID.ecPublicKey ? "ec" : "rsa"))
    throw new PkiPolicyError("The CSR public key does not match its algorithm.");
  assertClientKeyPolicy(publicKey);
  // The key must round-trip to the exact submitted bytes: no alternate or trailing encodings.
  if (!x509.spkiDer(publicKey).equals(spki.raw))
    throw new PkiPolicyError("The CSR public key is not canonically encoded.");
  return publicKey;
}

/**
 * Parse and check a PKCS#10 CSR: one strict PEM block of at most 16 KiB, a DER structure that
 * matches RFC 2986 exactly, a key within `assertClientKeyPolicy`, a self-signature that verifies,
 * and requested extensions within the client profile. Requested values are checked but never
 * copied; the issued profile is fixed. Every failure is a `CsrError`. Returns the public key.
 */
export function validateCsr(csrPem: string): KeyObject {
  if (typeof csrPem !== "string" || !csrPem) throw new CsrError("The CSR is missing.");
  if (csrPem.length > MAX_CSR_PEM_BYTES || Buffer.byteLength(csrPem, "utf8") > MAX_CSR_PEM_BYTES)
    throw new CsrError(`The CSR is larger than ${MAX_CSR_PEM_BYTES / 1024} KiB.`);
  try {
    const der = x509.fromPem(csrPem, ["CERTIFICATE REQUEST", "NEW CERTIFICATE REQUEST"]);
    const parts = x509.children(x509.expectTag(x509.decode(der), 0x30, "a CertificationRequest"));
    if (parts.length !== 3) throw new x509.DerError("Malformed CertificationRequest.");
    const [info, algorithm, signature] = parts as [x509.Node, x509.Node, x509.Node];
    const fields = x509.children(x509.expectTag(info, 0x30, "a CertificationRequestInfo"));
    if (fields.length < 3 || fields.length > 4)
      throw new x509.DerError("Malformed CertificationRequestInfo.");
    if (x509.decodeInteger(fields[0], "a CSR version", { maxBytes: 1 }) !== 0n)
      throw new PkiPolicyError("Only version 1 CSRs are accepted.");
    assertCsrName(fields[1]);
    if (fields[3] && fields[3].tag !== 0xa0) throw new x509.DerError("Malformed CSR attributes.");
    const publicKey = readCsrPublicKey(fields[2]);

    const algorithmParts = x509.children(x509.expectTag(algorithm, 0x30, "a signature AlgorithmIdentifier"));
    if (algorithmParts.length > 2) throw new x509.DerError("Malformed signature AlgorithmIdentifier.");
    const scheme = CSR_SIGNATURES[x509.decodeOid(algorithmParts[0])];
    if (!scheme || scheme.keyType !== publicKey.asymmetricKeyType)
      throw new PkiPolicyError("The CSR signature algorithm is not accepted for its key.");
    const parameters = algorithmParts[1];
    if (
      parameters &&
      !(scheme.keyType === "rsa" && parameters.tag === 0x05 && parameters.content.length === 0)
    )
      throw new PkiPolicyError("The CSR signature algorithm has unexpected parameters.");
    const signatureBits = x509.decodeBitString(signature, "a signature BIT STRING");
    if (signatureBits.unused !== 0 || !signatureBits.bytes.length)
      throw new x509.DerError("Malformed CSR signature.");
    let verified = false;
    try {
      verified = verify(scheme.hash, info.raw, publicKey, signatureBits.bytes);
    } catch {
      verified = false;
    }
    if (!verified) throw new PkiPolicyError("The CSR signature does not verify.");

    const attributes = fields[3] ? x509.children(fields[3]) : [];
    if (attributes.length > MAX_CSR_ATTRIBUTES)
      throw new PkiPolicyError("The CSR carries too many attributes.");
    let extensionRequests = 0;
    for (const attribute of attributes) {
      const [type, values, ...rest] = x509.children(x509.expectTag(attribute, 0x30, "an Attribute"));
      if (rest.length) throw new x509.DerError("Malformed CSR attribute.");
      const id = x509.decodeOid(type);
      if (id !== x509.OID.extensionRequest)
        throw new PkiPolicyError(`The CSR carries attribute ${id}, which is not accepted.`);
      if ((extensionRequests += 1) > 1) throw new PkiPolicyError("The CSR repeats its extension request.");
      const requested = x509.children(x509.expectTag(values, 0x31, "an attribute value SET"));
      if (requested.length !== 1) throw new PkiPolicyError("The CSR must carry one extension request.");
      assertRequestedExtensions(x509.parseExtensions(requested[0]!));
    }
    return publicKey;
  } catch (error) {
    if (error instanceof CsrError) throw error;
    if (error instanceof PkiPolicyError) throw new CsrError(error.message);
    if (error instanceof x509.DerError) throw new CsrError(`The CSR is malformed: ${error.message}`);
    throw new CsrError("The CSR is malformed.");
  }
}

export type RevokedEntry = { serial: string; revokedAt: Date; reason?: CrlReason | null };

/**
 * A v2 CRL signed by the CA: AKI and a CRL number, `thisUpdate` and `nextUpdate`, and one entry
 * per revoked serial (with a reasonCode extension unless the reason is unspecified).
 */
export function buildCrl(input: {
  ca: CaSigner;
  revoked: RevokedEntry[];
  thisUpdate: Date;
  nextUpdate: Date;
  crlNumber: bigint;
}) {
  const issuer = inspectSigner(input.ca);
  const thisUpdate = wholeSeconds(input.thisUpdate);
  const nextUpdate = wholeSeconds(input.nextUpdate);
  if (nextUpdate <= thisUpdate) throw new PkiPolicyError("nextUpdate must be after thisUpdate.");
  const entries = input.revoked.map((entry) => {
    if (!/^[0-9A-F]+$/.test(entry.serial)) throw new Error("Revoked serials must be uppercase hex.");
    const serial = Buffer.from(entry.serial.length % 2 ? `0${entry.serial}` : entry.serial, "hex");
    const code = entry.reason && Object.hasOwn(CRL_REASONS, entry.reason) ? CRL_REASONS[entry.reason] : 0;
    return x509.sequence(
      x509.integerFromBytes(serial),
      x509.time(wholeSeconds(entry.revokedAt)),
      ...(code ? [x509.sequence(x509.extension(x509.OID.crlReason, false, x509.enumerated(code)))] : []),
    );
  });
  const tbs = x509.sequence(
    x509.integer(1), // v2
    x509.ecdsaWithSha256(),
    issuer.subjectDer,
    x509.time(thisUpdate),
    x509.time(nextUpdate),
    ...(entries.length ? [x509.sequence(...entries)] : []),
    x509.explicit(
      0,
      x509.sequence(
        x509.extension(
          x509.OID.authorityKeyIdentifier,
          false,
          x509.authorityKeyIdentifierValue(issuer.keyId),
        ),
        x509.extension(x509.OID.crlNumber, false, x509.integer(input.crlNumber)),
      ),
    ),
  );
  const der = x509.signStructure(tbs, input.ca.privateKey);
  return { crlPem: x509.toPem("X509 CRL", der), thisUpdate, nextUpdate, crlNumber: input.crlNumber };
}

// ---- Persistence --------------------------------------------------------------------------------

type Database = typeof db;
type Transaction = Parameters<Parameters<Database["transaction"]>[0]>[0];
export type Executor = Database | Transaction;

function sealingKey() {
  const env = loadEnv();
  return { rootKey: env.rootKey, rootKeyId: env.rootKeyId };
}

type PrivateCaRow = typeof privateCas.$inferSelect;
type ClientCertificateRow = typeof clientCertificates.$inferSelect;

/** Inventory view of a CA: metadata and public PEMs only. Never the key or its secret ID. */
export type PrivateCaSummary = {
  id: string;
  purpose: CaPurpose;
  name: string;
  status: CaStatus;
  certPem: string;
  serial: string;
  fingerprintSha256: string;
  notBefore: Date;
  notAfter: Date;
  crlPem: string | null;
  crlNextUpdate: Date | null;
  createdAt: Date;
};

function summarizeCa(row: PrivateCaRow): PrivateCaSummary {
  const der = x509.fromPem(row.certPem, ["CERTIFICATE"]);
  const parsed = x509.parseCertificate(der);
  return {
    id: row.id,
    purpose: row.purpose,
    name: row.name,
    status: row.status,
    certPem: row.certPem,
    serial: parsed.serial,
    fingerprintSha256: x509.sha256Hex(der),
    notBefore: parsed.notBefore,
    notAfter: row.notAfter,
    crlPem: row.crlPem,
    crlNextUpdate: row.crlNextUpdate,
    createdAt: row.createdAt,
  };
}

/** Inventory view of a client certificate. `keySecretId` is the one-time reveal handle, if any. */
export type ClientCertificateSummary = Omit<ClientCertificateRow, "certPem"> & { certPem: string | null };

function summarizeCertificate(row: ClientCertificateRow): ClientCertificateSummary {
  return { ...row };
}

/**
 * Create a CA, seal its key, and record it. Returns metadata only. Pass `executor` to make the CA
 * part of the caller's transaction (FD-28 issues a rollover generation and links its successor
 * certificate atomically); it then runs in a savepoint.
 */
export async function createPrivateCa(
  input: {
    purpose: CaPurpose;
    name: string;
    now?: Date;
  },
  executor: Executor = db,
): Promise<PrivateCaSummary> {
  const { rootKey, rootKeyId } = sealingKey();
  const id = createId("pca");
  const material = createCaMaterial({ id, purpose: input.purpose, name: input.name, now: input.now });
  const keySecretId = createId("sec");
  const sealed = encryptSecret(
    rootKey,
    material.privateKey.export({ type: "pkcs8", format: "pem" }) as string,
    rootKeyId,
  );
  const row = await executor.transaction(async (tx) => {
    await tx.insert(secrets).values({
      id: keySecretId,
      kind: CA_KEY_SECRET_KIND,
      resourceType: "private_ca",
      resourceId: id,
      purpose: input.purpose,
      sensitivity: "root",
      once: false,
      ...sealed,
    });
    const [inserted] = await tx
      .insert(privateCas)
      .values({
        id,
        purpose: input.purpose,
        name: input.name,
        certPem: material.certPem,
        keySecretId,
        notAfter: material.notAfter,
        status: "active",
        ...(input.now ? { createdAt: input.now } : {}),
      })
      .returning();
    return inserted!;
  });
  return summarizeCa(row);
}

export async function getPrivateCa(id: string) {
  const [row] = await db.select().from(privateCas).where(eq(privateCas.id, id));
  return row ? summarizeCa(row) : null;
}

export async function listPrivateCas(filter: { purpose?: CaPurpose; status?: CaStatus } = {}) {
  const conditions = [
    filter.purpose ? eq(privateCas.purpose, filter.purpose) : undefined,
    filter.status ? eq(privateCas.status, filter.status) : undefined,
  ].filter((item) => item !== undefined);
  const rows = await db
    .select()
    .from(privateCas)
    .where(conditions.length ? and(...conditions) : undefined)
    .orderBy(asc(privateCas.createdAt), asc(privateCas.id));
  return rows.map(summarizeCa);
}

/**
 * Retire (no new issuance) or revoke a CA. Revocation is final. The PgBouncer client CA bundle
 * (FD-16) drops a revoked CA on its next `pgbouncer.reload`; HAProxy consumers (FD-14 route CAs) drop it when their route is rendered next.
 */
export async function setPrivateCaStatus(id: string, status: Exclude<CaStatus, "active">) {
  return db.transaction(async (tx) => {
    const [current] = await tx.select().from(privateCas).where(eq(privateCas.id, id)).for("update");
    if (!current) throw new PkiPolicyError("CA not found.");
    if (current.status === "revoked") return summarizeCa(current);
    const [row] = await tx.update(privateCas).set({ status }).where(eq(privateCas.id, id)).returning();
    return summarizeCa(row!);
  });
}

/** Unseal a CA key for signing, inside the caller's transaction. Internal to this module. */
async function loadSigner(executor: Executor, ca: PrivateCaRow): Promise<CaSigner> {
  const [secret] = await executor.select().from(secrets).where(eq(secrets.id, ca.keySecretId));
  if (!secret || secret.kind !== CA_KEY_SECRET_KIND || secret.resourceId !== ca.id)
    throw new Error("The CA key secret is missing or does not belong to this CA.");
  const { rootKey } = sealingKey();
  const privateKey = createPrivateKey(decryptSecret(rootKey, secret));
  return { certPem: ca.certPem, privateKey };
}

const KEY_OWNER_TABLES = {
  database: managedDatabases,
  mailbox: mailboxes,
  domain: domainClaims,
  service: services,
  project: projects,
} as const;
export type ClientKeyOwner = {
  resourceType: keyof typeof KEY_OWNER_TABLES | "platform";
  resourceId: string;
};

/** Match the resources resolved by the generic reveal endpoint; never invent an owner. */
async function assertKeyOwner(executor: Executor, owner: ClientKeyOwner | undefined) {
  if (!owner || !owner.resourceId)
    throw new PkiPolicyError("Generated client keys require a supported keyOwner.");
  if (owner.resourceType === "platform" && owner.resourceId === "platform") return;
  if (!Object.hasOwn(KEY_OWNER_TABLES, owner.resourceType))
    throw new PkiPolicyError("Unsupported generated client key owner.");
  const table = KEY_OWNER_TABLES[owner.resourceType as keyof typeof KEY_OWNER_TABLES];
  const [row] = await executor.select({ id: table.id }).from(table).where(eq(table.id, owner.resourceId));
  if (!row) throw new PkiPolicyError("Generated client key owner not found.");
}

export type IssueClientCertificateInput = {
  caId: string;
  /** The client's login-role name, for audit only (§3.10.1). */
  subjectCn: string;
  /** Advanced issuance: sign this CSR; the key never touches Ark. Omit to generate a key. */
  csrPem?: string;
  rolloverState?: "current" | "pending";
  /**
   * The resource that owns the sealed generated key, for the generic reveal endpoint's scope
   * check (FD-17 passes the database). Required for generated keys; must exist.
   */
  keyOwner?: ClientKeyOwner;
  now?: Date;
};

/**
 * Issue a 90-day client certificate from an active CA. With no CSR, Ark generates an ECDSA P-256
 * key and seals it as a `once` secret for the existing one-time reveal. Returns metadata, the
 * public certificate and the CA certificate; never the private key. `executor` joins the
 * caller's transaction (savepoint), as for createPrivateCa.
 */
export async function issueClientCertificate(input: IssueClientCertificateInput, executor: Executor = db) {
  const csrKey = input.csrPem === undefined ? null : validateCsr(input.csrPem);
  const { rootKey, rootKeyId } = sealingKey();
  return executor.transaction(async (tx) => {
    const [ca] = await tx.select().from(privateCas).where(eq(privateCas.id, input.caId)).for("share");
    if (!ca) throw new PkiPolicyError("CA not found.");
    if (ca.status !== "active") throw new PkiPolicyError(`The CA is ${ca.status}; it cannot issue.`);
    if (!csrKey) await assertKeyOwner(tx, input.keyOwner);
    const signer = await loadSigner(tx, ca);
    const id = createId("ccert");
    let keySecretId: string | null = null;
    let publicKey = csrKey;
    let generatedPem: string | null = null;
    if (!publicKey) {
      const pair = generateKeyPairSync("ec", { namedCurve: "P-256" });
      publicKey = pair.publicKey;
      generatedPem = pair.privateKey.export({ type: "pkcs8", format: "pem" }) as string;
    }
    const issued = signClientCertificate({
      ca: signer,
      subjectCn: input.subjectCn,
      publicKey,
      now: input.now,
    });
    if (generatedPem !== null) {
      keySecretId = createId("sec");
      const owner = input.keyOwner!;
      await tx.insert(secrets).values({
        id: keySecretId,
        kind: CLIENT_KEY_SECRET_KIND,
        resourceType: owner.resourceType,
        resourceId: owner.resourceId,
        purpose: ca.purpose,
        sensitivity: "credential",
        once: true,
        ...encryptSecret(rootKey, generatedPem, rootKeyId),
      });
    }
    const [row] = await tx
      .insert(clientCertificates)
      .values({
        id,
        caId: ca.id,
        subjectCn: input.subjectCn,
        serial: issued.serial,
        fingerprintSha256: issued.fingerprintSha256,
        notBefore: issued.notBefore,
        notAfter: issued.notAfter,
        certPem: issued.certPem,
        keySecretId,
        status: "issued",
        rolloverState: input.rolloverState ?? "current",
        ...(input.now ? { createdAt: input.now } : {}),
      })
      .returning();
    return { certificate: summarizeCertificate(row!), caCertPem: ca.certPem };
  });
}

export async function getClientCertificate(id: string) {
  const [row] = await db.select().from(clientCertificates).where(eq(clientCertificates.id, id));
  return row ? summarizeCertificate(row) : null;
}

export async function listClientCertificates(caId: string) {
  const rows = await db
    .select()
    .from(clientCertificates)
    .where(eq(clientCertificates.caId, caId))
    .orderBy(asc(clientCertificates.createdAt), asc(clientCertificates.id));
  return rows.map(summarizeCertificate);
}

/**
 * Revoke a client certificate (idempotent). An unrevealed generated key is destroyed with it.
 * The next `generateCaCrl` lists the serial; PgBouncer has no CRL, so DB clients also need the
 * CA removal and role drain of §3.10.4 (FD-17/FD-28).
 */
export async function revokeClientCertificate(input: { id: string; reason?: CrlReason; now?: Date }) {
  const reason = input.reason ?? "unspecified";
  if (!Object.hasOwn(CRL_REASONS, reason)) throw new PkiPolicyError("Unknown revocation reason.");
  return db.transaction(async (tx) => {
    const [current] = await tx
      .select()
      .from(clientCertificates)
      .where(eq(clientCertificates.id, input.id))
      .for("update");
    if (!current) throw new PkiPolicyError("Client certificate not found.");
    if (current.status === "revoked") return summarizeCertificate(current);
    const [row] = await tx
      .update(clientCertificates)
      .set({
        status: "revoked",
        revokedAt: wholeSeconds(input.now ?? new Date()),
        revokedReason: reason,
        keySecretId: null,
      })
      .where(and(eq(clientCertificates.id, input.id), ne(clientCertificates.status, "revoked")))
      .returning();
    if (current.keySecretId) await tx.delete(secrets).where(eq(secrets.id, current.keySecretId));
    return summarizeCertificate(row!);
  });
}

/**
 * Generate and store the CA's CRL: every revoked certificate of this CA, `thisUpdate = now`, and
 * `nextUpdate = now + nextUpdateDays` (default 14). The CRL number increases monotonically.
 */
export async function generateCaCrl(input: { caId: string; nextUpdateDays?: number; now?: Date }) {
  const days = input.nextUpdateDays ?? DEFAULT_CRL_NEXT_UPDATE_DAYS;
  if (!Number.isFinite(days) || days <= 0 || days > 366)
    throw new PkiPolicyError("nextUpdate must be between 0 and 366 days ahead.");
  return db.transaction(async (tx) => {
    const [ca] = await tx.select().from(privateCas).where(eq(privateCas.id, input.caId)).for("update");
    if (!ca) throw new PkiPolicyError("CA not found.");
    const signer = await loadSigner(tx, ca);
    const revoked = await tx
      .select()
      .from(clientCertificates)
      .where(and(eq(clientCertificates.caId, ca.id), eq(clientCertificates.status, "revoked")))
      .orderBy(desc(clientCertificates.revokedAt), asc(clientCertificates.serial));
    const thisUpdate = wholeSeconds(input.now ?? new Date());
    const nextUpdate = new Date(thisUpdate.getTime() + Math.round(days * DAY_MS));
    // A CRL number from the clock, kept strictly above the stored CRL's, needs no extra column.
    const previous = ca.crlPem ? x509.parseCrl(x509.fromPem(ca.crlPem, ["X509 CRL"])).crlNumber : null;
    const fromClock = BigInt(Math.floor(thisUpdate.getTime() / 1000));
    const crlNumber = previous !== null && previous >= fromClock ? previous + 1n : fromClock;
    const crl = buildCrl({
      ca: signer,
      revoked: revoked.map((row) => ({
        serial: row.serial,
        revokedAt: row.revokedAt ?? row.createdAt,
        reason: (row.revokedReason ?? null) as CrlReason | null,
      })),
      thisUpdate,
      nextUpdate,
      crlNumber,
    });
    await tx
      .update(privateCas)
      .set({ crlPem: crl.crlPem, crlNextUpdate: crl.nextUpdate })
      .where(eq(privateCas.id, ca.id));
    // The CRL number is returned as a decimal string so the result is JSON-safe for API callers.
    return {
      ...crl,
      crlNumber: crl.crlNumber.toString(),
      caId: ca.id,
      revokedSerials: revoked.map((row) => row.serial),
    };
  });
}
